cmd:
cd /opt/weather-pipeline/repo
git log --oneline -1
echo ===IMPORT-CHECK===
python3 -c "import sys; sys.path.insert(0,'scripts'); import open_meteo_guard as g; print('gate:', g.gate(probe_owner=False)); print('status:', g.status())"
echo ===AST-CHECK===
for f in scripts/vps_pipeline.py scripts/update.py scripts/open_meteo_frontal_confirm.py scripts/open_meteo_field_fetch.py scripts/open_meteo_very_far_line.py scripts/open_meteo_guard.py; do
  python3 -c "import ast; ast.parse(open('$f').read()); print('$f OK')" || echo "$f FAIL"
done
echo ===LS-DATA===
ls -la data/_open_meteo_cooldown* 2>/dev/null || echo "no cooldown files yet (expected before first trip)"
